"""Generate the meme archive from the reviewed catalogue. No network or AI calls."""
from pathlib import Path
from html import escape as esc
import json, re, xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/memes';SITE='https://elcontemplador.github.io/estrategIA-lab/';BASE=SITE+'memes/'
catalog=json.loads((ROOT/'data/memes/catalog.json').read_text(encoding='utf-8'))
items=sorted(catalog['items'],key=lambda x:(-x['issue'],x['order']))
latest=items[0]
cutoff=catalog['cutoffIssue']
assert latest['issue']<=cutoff and latest['date']<=catalog['cutoffDate'], 'Catalogue cutoff must cover every published piece'
TAGS={'politica':'Política y gobierno','trabajo':'Trabajo y vida cotidiana','usar-ia':'Usos y capacidades de la IA','poder':'Poder y empresas','regulacion':'Regulación y riesgos','informacion':'Información y creatividad'}
MONTHS=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']
def date(d,short=False):
 y,m,day=d.split('-');return f'{int(day)} {MONTHS[int(m)-1][:3] if short else MONTHS[int(m)-1]} {y}'
def js(data):return json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
def head(title,description,path='',image=None,asset_prefix=''):
 image=image or latest['id']
 return f'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{esc(title)} · estrategIA</title><meta name="description" content="{esc(description,quote=True)}">
<meta name="theme-color" content="#9d2235"><link rel="canonical" href="{BASE+path}">
<meta property="og:type" content="website"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{BASE+path}"><meta property="og:image" content="{BASE}assets/{image}-large.webp"><meta property="og:image:alt" content="{esc(title,quote=True)}"><meta property="og:site_name" content="estrategIA lab"><meta property="og:locale" content="es_ES"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="{asset_prefix}../favicon.ico"><link rel="stylesheet" href="{asset_prefix}memes.css"><script defer src="{asset_prefix}memes.js"></script></head><body>
<a class="skip" href="#main">Saltar al contenido</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="{asset_prefix}../" aria-label="Inicio de estrategIA lab">estrategIA <span>lab</span></a><nav class="header-nav" aria-label="Navegación principal"><a class="lab-link" href="{asset_prefix}../#proyectos">Volver al LAB</a><a href="https://estrategiabyaleph.substack.com/">La newsletter <span aria-hidden="true">↗</span></a></nav></div></header>'''
def footer(prefix=''):
 return f'''<footer class="site-footer"><div class="wrap footer-inner"><div><p class="footer-brand">estrategIA</p><p>Una newsletter de la Institución Educativa ALEPH.</p></div><p><a href="{prefix}../">Volver al LAB</a> &nbsp;·&nbsp; <a href="https://estrategiabyaleph.substack.com/subscribe">Suscribirse a estrategIA</a></p></div></footer></body></html>'''
def card(x,prefix='',related=False):
 thumb_width=min(x['width'],round(x['width']*640/max(x['width'],x['height'])))
 large_width=min(x['width'],round(x['width']*1600/max(x['width'],x['height'])))
 srcset=f' srcset="{prefix}assets/{x["id"]}-thumb.webp {thumb_width}w, {prefix}assets/{x["id"]}-large.webp {large_width}w"' if large_width>thumb_width else ''
 return f'''<article class="meme-card" id="meme-{x['id']}" data-id="{x['id']}"><a class="meme-link" href="{prefix}{x['id']}/"><div class="meme-frame"><img src="{prefix}assets/{x['id']}-thumb.webp"{srcset} sizes="(max-width:520px) calc(100vw - 54px), (max-width:760px) 45vw, 30vw" width="{x['width']}" height="{x['height']}" alt="{esc(x['alt'],quote=True)}" loading="lazy" decoding="async"></div><div class="card-copy"><div class="card-meta"><span class="issue">estrategIA #{x['issue']}</span><span class="dot" aria-hidden="true">·</span><time datetime="{x['date']}">{date(x['date'],True)}</time></div><h2>{esc(x['title'])}</h2><div class="card-action">Ver contexto <span aria-hidden="true">↗</span></div></div></a></article>'''

cutoff_year,cutoff_month,cutoff_day=catalog['cutoffDate'].split('-')
cutoff_label=f'{int(cutoff_day)} de {MONTHS[int(cutoff_month)-1]} de {cutoff_year}'
intro=f'''<main id="main" class="wrap"><section class="intro" aria-labelledby="archive-title"><div><p class="eyebrow">El archivo de humor · {min(x['date'][:4] for x in items)} — {cutoff_year}</p><h1 id="archive-title">Los memes de <em>estrategIA.</em></h1><p class="lede">IA, política y gobierno, también con humor.<span class="desktop-intro"><br>Las imágenes que publicamos, con su contexto y su historia.</span></p></div><aside class="archive-note" aria-label="Sobre la colección"><span class="big-number">{len(items)}</span><p>piezas de nuestros primeros<br>{cutoff} números.</p><a href="#sobre-el-archivo">Sobre este archivo ↓</a></aside></section>'''
options=''.join(f'<option value="{key}">{label}</option>' for key,label in TAGS.items())
filters=f'''<form id="archive-filters" class="tools" role="search" aria-label="Buscar memes" hidden><div class="search"><label for="query">¿Qué meme buscas?</label><div class="search-field"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="query" name="q" type="search" placeholder="Un tema, una frase o el número…" autocomplete="off"></div></div><div class="filter-group" id="filters-extra"><div class="filter"><label for="theme">Tema</label><select id="theme" name="tema"><option value="">Todos los temas</option>{options}</select></div><div class="filter"><label for="year">Año</label><select id="year" name="ano"><option value="">Todos los años</option>{''.join(f'<option>{y}</option>' for y in sorted({x['date'][:4] for x in items},reverse=True))}</select></div><div class="filter order-filter"><label for="order">Orden</label><select id="order" name="orden"><option value="recientes">Más recientes</option><option value="antiguos">Desde el principio</option></select></div></div></form><noscript><p class="no-js-note">Puedes recorrer la colección completa y abrir cada ficha. Activa JavaScript si quieres usar el buscador y los filtros.</p></noscript><div class="results-bar"><span id="result-count" role="status" aria-live="polite">{len(items)} memes</span><button class="filter-toggle" type="button" id="filter-toggle" aria-expanded="false" aria-controls="filters-extra" hidden>Filtros y orden</button><span class="scope-label">Números 1–{cutoff} · Imágenes completas, sin recortes</span><button class="reset" type="button" id="reset" hidden>Limpiar filtros</button></div>'''
about=f'''<section class="about" id="sobre-el-archivo" aria-labelledby="about-title"><div><p class="eyebrow">El contexto también cuenta</p><h2 id="about-title">Una forma de volver<br>a aquellas semanas.</h2></div><div><p>Desde octubre de 2023, los memes acompañan nuestra conversación sobre inteligencia artificial, política y gobierno. Aquí puedes volver a ellos, entender una referencia y regresar al número en el que aparecieron.</p><p>Este archivo reúne {len(items)} piezas publicadas en los primeros {cutoff} números, hasta el {cutoff_label}. Conservamos las imágenes completas, sus textos y sus créditos visibles. Las explicaciones se han preparado para este archivo y sitúan cada pieza en su momento; las noticias, herramientas y expectativas son las de entonces.</p><details><summary>Cómo está organizado el archivo</summary><p>La colección incluye memes, viñetas y piezas visuales publicadas en la sección de humor. Cada imagen cuenta como una pieza: una secuencia de viñetas dentro de la misma imagen permanece unida. Las versiones diferentes publicadas juntas conservan fichas propias.</p><p>Se han revisado los {cutoff} números. Las ediciones 13, 65, 117 y 118 son especiales sin un meme independiente en el cuerpo de la newsletter. Las felicitaciones, los banners de patrocinio y los documentos externos enlazados quedan fuera de la galería.</p><p>La publicación en estrategIA no implica autoría de todos los elementos gráficos. Los créditos identificados figuran en sus fichas. El texto de las imágenes está transcrito para facilitar su lectura y búsqueda; conserva el idioma y las peculiaridades del original.</p></details><p><a href="https://estrategiabyaleph.substack.com/archive">Explorar los números completos de estrategIA ↗</a></p></div></section>'''
html=head('Los memes de estrategIA','El archivo de humor de estrategIA: memes sobre IA, política y gobierno, con imágenes completas, contexto y enlaces a sus números originales.')+intro+filters+'<div class="archive-grid" id="gallery">'+''.join(card(x) for x in items)+'</div>'+'''<div class="empty" id="empty" hidden><h2>No encontramos ese meme.</h2><p>Prueba otra palabra, un número de newsletter o elimina los filtros.</p><button class="button secondary" id="clear-empty" type="button">Ver todos los memes</button></div><div class="load-area" id="load-area" hidden><button class="button secondary" id="load-more" type="button">Ver más memes <span aria-hidden="true">↓</span></button><p class="load-progress" id="load-progress"></p></div>'''+about+f'<script id="archive-data" type="application/json">{js(items)}</script></main>'+footer()
OUT.mkdir(parents=True,exist_ok=True);(OUT/'index.html').write_text(html,encoding='utf-8')

for idx,x in enumerate(items):
 folder=OUT/x['id'];folder.mkdir(exist_ok=True)
 related=sorted([y for y in items if y['id']!=x['id']],key=lambda y:(y['issue']!=x['issue'],-len(set(y['tags'])&set(x['tags'])),abs(y['issue']-x['issue'])))[:3]
 tags=''.join(f'<a class="tag" href="../?tema={t}">{TAGS[t]}</a>' for t in x['tags'])
 prev=items[idx-1] if idx else None; nxt=items[idx+1] if idx+1<len(items) else None
 nav=f'<nav class="piece-navigation" aria-label="Recorrer la colección"><a data-previous href="../{prev["id"] if prev else x["id"]}/"{ " hidden" if not prev else ""}>← Meme más reciente</a><a data-next href="../{nxt["id"] if nxt else x["id"]}/"{ " hidden" if not nxt else ""}>Meme anterior en el archivo →</a></nav>'
 meta={'@context':'https://schema.org','@type':'ImageObject','name':x['title'],'description':x['context'],'contentUrl':BASE+'assets/'+x['id']+'-large.webp','url':BASE+x['id']+'/','datePublished':x['date'],'inLanguage':'es','isPartOf':{'@type':'CreativeWork','name':x['issueTitle'],'url':x['issueUrl']}}
 detail=f'''<main id="main" class="wrap" data-meme-id="{x['id']}"><div class="breadcrumb"><a data-back href="../">← Volver a la galería</a><span aria-hidden="true">/</span><span>#{x['issue']}</span></div><article class="detail-layout"><figure class="detail-art"><a class="image-link" id="enlarge" href="../assets/{x['id']}-large.webp" aria-label="Ampliar imagen: {esc(x['title'],quote=True)}"><img src="../assets/{x['id']}-large.webp" width="{x['width']}" height="{x['height']}" alt="{esc(x['alt'],quote=True)}" aria-describedby="transcript" fetchpriority="high"></a><figcaption class="image-caption"><span>Imagen completa · Pulsa para ampliar</span><a href="{x['originalUrl']}" target="_blank" rel="noopener">Ver original ↗<span class="sr-only"> (abre en otra pestaña)</span></a></figcaption></figure><div class="detail-copy"><p class="eyebrow">estrategIA #{x['issue']} · <time datetime="{x['date']}">{date(x['date'])}</time></p><h1>{esc(x['title'])}</h1><div class="tags" aria-label="Temas">{tags}</div><section class="context-block" aria-labelledby="context-title"><h2 id="context-title">El contexto</h2><p>{esc(x['context'])}</p></section><div class="detail-actions"><a class="button" href="{esc(x['issueUrl'],quote=True)}">Leer estrategIA #{x['issue']} <span aria-hidden="true">↗</span></a><button class="button secondary" id="copy-link" type="button" hidden>Copiar enlace</button></div><p class="source-title">Publicado en: {esc(x['issueTitle'])}</p><p class="copy-status" id="copy-status" role="status" aria-live="polite"></p><input class="share-fallback" id="share-fallback" aria-label="Enlace de esta ficha para copiar" readonly hidden><details class="transcription"><summary>Leer el texto de la imagen</summary><p id="transcript">{esc(x['transcript'])}</p></details>{'<p class="credit">'+esc(x['credit'])+'</p>' if x['credit'] else ''}</div></article>{nav}<section class="related" aria-labelledby="related-title"><div class="related-head"><h2 id="related-title">Para seguir explorando</h2><a href="../">Todo el archivo →</a></div><div class="archive-grid">{''.join(card(y,'../',True) for y in related)}</div></section><script type="application/ld+json">{js(meta)}</script></main><dialog class="lightbox" id="lightbox" aria-label="Imagen ampliada"><div class="lightbox-head"><a href="{x['originalUrl']}" target="_blank" rel="noopener">Abrir original para ampliar más ↗</a><button type="button" id="close-lightbox" autofocus>Cerrar ×</button></div><div class="lightbox-body"><img src="../assets/{x['id']}-large.webp" alt="{esc(x['alt'],quote=True)}" width="{x['width']}" height="{x['height']}"></div></dialog>'''
 (folder/'index.html').write_text(head(x['title'],x['context'],x['id']+'/',x['id'],'../')+detail+footer('../'),encoding='utf-8')

# Integrate in the LAB catalogue without changing unrelated projects.
home=ROOT/'docs/index.html';text=home.read_text(encoding='utf-8')
new=f'''          <article id="archivo-memes" class="project-card" aria-labelledby="memes-title">
            <figure class="project-media"><img src="memes/assets/{latest['id']}-thumb.webp" alt="{esc(latest['alt'],quote=True)}" width="{latest['width']}" height="{latest['height']}" loading="lazy" style="object-fit:contain"></figure>
            <div class="project-copy"><p class="project-type">Mirar la IA con humor</p><h3 id="memes-title">Los memes de estrategIA</h3><p>{len(items)} memes y viñetas de nuestros primeros {cutoff} números. Las imágenes completas, con una explicación breve de su contexto y un enlace a la newsletter en la que aparecieron. Busca una frase, un tema o una edición y recorre lo que hemos contado sobre IA, política y gobierno.</p><div class="project-meta"><span>Archivo visual</span><span>Navegador · sin cuenta</span></div></div>
            <div class="project-actions" aria-label="Acciones del archivo de memes"><a class="text-link" href="memes/">Explorar los memes</a><a class="context-link" href="memes/#sobre-el-archivo">Sobre el archivo</a></div>
          </article>
'''
if 'id="archivo-memes"' not in text:text=text.replace('<div class="project-list">','<div class="project-list">\n'+new,1)
else:text=re.sub(r'          <article id="archivo-memes".*?</article>\n',new,text,count=1,flags=re.S)
home.write_text(text,encoding='utf-8')
sitemap=ROOT/'docs/sitemap.xml';NS='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',NS);tree=ET.parse(sitemap);root=tree.getroot()
for child in list(root):
 loc=child.find('{'+NS+'}loc')
 if loc is not None and loc.text.startswith(BASE):root.remove(child)
for path in ['']+[x['id']+'/' for x in items]:
 url=ET.SubElement(root,'{'+NS+'}url');ET.SubElement(url,'{'+NS+'}loc').text=BASE+path;ET.SubElement(url,'{'+NS+'}lastmod').text=catalog['compiledDate']
ET.indent(tree);tree.write(sitemap,encoding='utf-8',xml_declaration=True)
print(f'Built gallery and {len(items)} detail pages; LAB card and sitemap updated.')
